// allows executing `cds serve` even when `cds` executable is removed from `@sap/cds`
const { DIR } = require('./completion');
const serve = require(_local('@sap/cds/bin/serve'))
module.exports = Object.assign(serve, {
  staticCompletions: () => ({
    '_':      DIR(),
    '--from': DIR(),
    '-f':     DIR(),
    '--with': DIR(),
    '-w':     DIR(),
    '--to':   ['odata', 'fiori', 'rest'],
    '-2':     ['odata', 'fiori', 'rest'],
  }),
})

function _local (id) {
  return require.resolve (id, { paths: [ process.cwd(), __dirname ] })
}